import { registerWebComponents } from '@domg-wc/common';
import { VlAccordionComponent } from '@domg-wc/components/block';

registerWebComponents([VlAccordionComponent]);

// vl-on-toggle volgt bij het openen en sluiten via de toggle; event.detail.open zegt of de accordion open is.
document.querySelector('vl-accordion').addEventListener('vl-on-toggle', (event) => {
    console.log(event.detail.open ? 'geopend' : 'gesloten');
});

