import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTextComponent } from '@domg-wc/components/atom';
import { VlAccordionComponent, VlPopoverComponent } from '@domg-wc/components/block';

// VlPopoverComponent laadt zelf vl-popover-action-list en vl-popover-action.
registerWebComponents([VlAccordionComponent, VlPopoverComponent, VlButtonComponent, VlTextComponent]);
